r := buildPublishBundle(ctx, opts, storage, repoDir)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"publish: %w\", err)\n\t}\n\n\tresult, err := postBrainArtifacts(ctx, baseURL, repoID, token, body)\n\tif err != nil {\n\t\treturn err\n\t}\n\n\tfmt.Fprintf(cmd.OutOrStdout(), \"published %d artifact(s) for %s to %s\\n\",\n\t\tlen(result.Stored), repoKey, strings.TrimRight(baseURL, \"/\"))\n\treturn nil\n}"},{"rank":2,"score":80.7683,"file_path":"internal/cli/publish.go","start_line":240,"end_line":245,"focus_line":240,"snippet_start_line":240,"snippet_end_line":245,"symbol_start_line":240,"symbol_end_line":245,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/publish.go:function:publishFlagOrEnv","symbol_name":"publishFlagOrEnv","qualified_name":"publishFlagOrEnv","signature":"func publishFlagOrEnv(flagVal, envName string) string","signals":["graph:calls","graph:outgoing","graph:callers"],"snippet":"func publishFlagOrEnv(flagVal, envName string) string {\n\tif v := strings.TrimSpace(flagVal); v != \"\" {\n\t\treturn v\n\t}\n\treturn strings.TrimSpace(os.Getenv(envName))\n}"},{"rank":3,"score":72.6915,"file_path":"internal/cli/facts_proposals_cmd.go","start_line":175,"end_line":208,"focus_line":185,"snippet_start_line":175,"snippet_end_line":208,"symbol_start_line":175,"symbol_end_line":208,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/facts_proposals_cmd.go:function:resolveHostedProposalTarget","symbol_name":"resolveHostedProposalTarget","qualified_name":"resolveHostedProposalTarget","signature":"func resolveHostedProposalTarget(ctx context.Context, opts Options, pOpts factsProposalsOptions) (hostedProposalTarget, error)","signals":["body","symbol-usage","complete-symbol"],"snippet":"func resolveHostedProposalTarget(ctx context.Context, opts Options, pOpts factsProposalsOptions) (hostedProposalTarget, error) {\n\t// The master local-only switch always wins over the hosted opt-in.\n\tif brainN